        <38, 1, {1,2,19,38}, [* <-4, QQ>, <-11, QQ>, <-19, QQ>, <-20, QQ>, <-24, QQ>, <-43, QQ>, <-163, QQ>, <-228, QQ>, <-232, QQ>, <-532, QQ>, <-760, QQ> *] >,
