    ];
    curves := GetHyperellipticCandidates();
    // Two lists of number fields are equal as SETS up to isomorphism (order/multiplicity ignored).
    // Depends only on its arguments (no closure over outer variables) to avoid the Magma 2.29
    // eval/closure segfault quirk.
    same_fields := function(A, B)
        for F in A do
            if not exists{G : G in B | IsIsomorphic(F, G)} then return false; end if;
        end for;
        for G in B do
            if not exists{F : F in A | IsIsomorphic(F, G)} then return false; end if;
        end for;
        return true;
    end function;
    for datum in data do
        D, N, W, cm := Explode(datum);
        assert exists(X){X : X in curves | X`D eq D and X`N eq N and X`W eq W};
        vprintf ShimuraQuotients, 1: "testing points on %o...", X;
        // The rational and degree-2 CM-point tables (CMFieldsOfDefinition.m) and the pipeline's own
        // scan (RationalandQuadraticCMPoints) must put every source-backed [GY] point in the right
        // table.  [GY] lists some but not necessarily all CM points, so these are membership checks.
        rat_tab := Keys(RationalCMDiscs(X));
        quad_tab := Keys(Degree2Points(X : compute_fields := false));
        rat_scan, quad_scan := RationalandQuadraticCMPoints(X : bd := 8, coprime_to_level := false);
        rat_scan := {p[1] : p in rat_scan};
        quad_scan := {p[1] : p in quad_scan};
        for pt in cm do
            d, K := Explode(pt);
            // CMClassLists stops at class number 8.  Every d in data has h <= 8, so this never
            // fires today; it is a guard for rows added later.
            if ClassNumber(d) gt 8 then continue; end if;
            // At bd := 8 the scan's candidate table is the FUNDAMENTAL discriminants of class
            // number 1, 2, 4 and 8 (its h = 16 part, unused here, has all orders).  Its elliptic
            // seeding can add non-fundamental discriminants (e.g. -12, from the fixed points of w_3),
            // but the table never scans them, so non-fundamental d are not checked against the scan.
            in_scan := IsFundamentalDiscriminant(d);
            if AbsoluteDegree(K) eq 1 then
                assert d in rat_tab and d notin quad_tab;
                if in_scan then assert d in rat_scan and d notin quad_scan; end if;
            elif AbsoluteDegree(K) eq 2 then
                assert d in quad_tab and d notin rat_tab;
                // Guards a fixed bug: the elliptic points d = -3, -4 were seeded as rational
                // whenever the STAR-quotient seeding conditions held, without checking the degree
                // of the field of definition on the actual (possibly proper) subquotient.  [GY]
                // witness (Table 16): d = -3 on X_0^58(1)/<w_29> has field Q(sqrt(-3)).  d = -4 on
                // (57,1,<w19>) and (93,1,<w31>) also catch it (and come first), but those two
                // values are provenance (b), solved from [GY]'s equations rather than printed.
                if in_scan then assert d in quad_scan and d notin rat_scan; end if;
            else
                assert d notin rat_tab and d notin quad_tab;
                if in_scan then assert d notin rat_scan and d notin quad_scan; end if;
            end if;
        end for;
        for pt in cm do
            d, K := Explode(pt);
            // The degree read off Pic(R) and W alone (CMFieldsOfDefinition.m) must match [GY] too
            // (every row of data is provenance (a) or (b), including the degree_only_pts rows).
            assert DegreeOfFieldOfDefinitionOfCMPoint(X, d) eq AbsoluteDegree(K);
            // Field disputed with [GY], unresolved: only the degree above is asserted.
            if exists{g : g in degree_only_pts | g eq <D, N, W, d>} then continue; end if;
            Fs := FieldsOfDefinitionOfCMPoint(X, d);
            // [GY] ground truth: K must be among the computed fields.
            assert exists(F){F : F in Fs | IsIsomorphic(F,K)};
            // Regression guard (added after the exponent>2 over-generation bug): the fast and slow
            // routines must agree as SETS up to isomorphism, and fast must also contain the ground
            // truth. The slow routine used to enumerate every order-2 automorphism restricting to
            // complex conjugation on K (spurious extra fields for Pic(R) of exponent > 2) instead of
            // the single genuine complex conjugation; the membership check above tolerated that, so it
            // went unnoticed. Asserting set-equality keeps either routine from silently drifting.
            Fs_fast := FieldsOfDefinitionOfCMPointFast(X, d);
            assert exists(F){F : F in Fs_fast | IsIsomorphic(F,K)};
            assert same_fields(Fs, Fs_fast);
        end for;
        vprintf ShimuraQuotients, 1: "Done!\n";
    end for;

    // (26,3,<w3,w26>), Table 49, d = -267 and d = -708: provenance (c).
    // [GY] arXiv v1 prints s = -9/25 (d=-267) and s = -27/49 (d=-708).  These are REFUTED by
    // Shimura reciprocity applied to [GY]'s own equations.  Reciprocity alone does not say what the
    // right value is; the replacement -s rests on the sign being the only misprint, and is backed
    // by a search (asserted below): among all rational s = a/b with |a|, b <= 400, the sign-flipped
    // value is the UNIQUE one passing the same three square conditions.  It agrees with the code.
    // The journal version may already correct this.
    // SOURCE OF TRUTH, two facts, neither of them this code:
    //  (i)  Shimura reciprocity: a CM point on X_0^D(N) by the order R (disc d) is defined over the
    //       ring class field H_R.  [GY]'s model is over Q, so every coordinate of the point lies in H_R.
    //  (ii) [GY] Table 8 ("Equations of level greater than one"): X_0^26(3) is
    //           z^2 = -8x^2 - 3,   y^2 = x^6 - 2x^4 + 9x^2 + 8,
    //       w2(x,y,z) = (-x,-y,-z), w3(x,y,z) = (x,-y,-z), w26(x,y,z) = (x,-y,z); and Table 49 gives s on
    //       X_0^26(3)/W and x on X_0^26(3)/<w3,w26> with s = x^2 (both column headers).
    // So given s, the point has x = sqrt(s), y = sqrt(s^3-2s^2+9s+8), z = sqrt(-8s-3), and all three
    // must lie in H_R.  Every other row of Table 49 passes as printed (asserted below, which also
    // checks that (i)+(ii) are being read correctly); at -267 and -708 the printed s fails and -s
    // passes.  With -s, Q(x) is Q at -267 and Q(sqrt(3)) at -708, and the code must give exactly that.
    // ⚠ CONFLICT, flagged for the coauthor (those files deliberately NOT edited here):
    // data/models/PROVENANCE.md, PLAN.md and the comments in SchoferFormula.m on the non-coprime CM
    // filter ("misbehave", "the s <-> s~ swap", "known-wrong ... STILL WRONG") currently treat
    // [GY]'s values at -267 and -708 as correct (the documented s <-> s~ swap in our 26_3 Schofer
    // values).  This test contradicts that.  Moreover, by those notes' own Mobius map from [GY]'s
    // coordinate w to ours, phi(w) = (1-w)/2 (PLAN.md, 26_3 entry), our Schofer values 8/25 (-267)
    // and 11/49 (-708) (PLAN.md table) are phi(9/25) and phi(27/49): exactly the sign-corrected
    // values, while [GY]'s printed -9/25 and -27/49 map to 17/25 and 38/49.  So the pipeline's
    // Schofer values at these two discs are the reciprocity-consistent ones.
    ring_class_field := function(d)
        K := QuadraticField(d); OK := MaximalOrder(K);
        f := Isqrt(d div Discriminant(OK));
        return AbsoluteField(NumberField(RingClassField(sub<OK | [1, f*OK.2]>)));
    end function;
    // <d, s as printed in [GY] arXiv v1 Table 49>; s = oo at d = -8 is encoded as the string "oo".
    table49 := [* <-8, "oo">, <-11, 1>, <-20, -1>, <-24, 0>, <-84, -3>, <-123, 9>, <-132, 3>,
                  <-195, -3/5>, <-228, -3/4>, <-267, -9/25>, <-312, -3/8>, <-372, -12>,
                  <-408, -3/25>, <-708, -27/49> *];
    bad_sign := [-267, -708];
    // The three quantities that must be squares in H_R.  At s = oo (x = oo) the point at infinity
    // has y/x^3 = +-1 and z/x = +-sqrt(-8), so the leading coefficients 1 and -8 must be squares.
    squares_needed := function(s)
        if Type(s) eq MonStgElt then return [Rationals() | 1, 1, -8]; end if;
        s := Rationals() ! s;
        return [s, s^3 - 2*s^2 + 9*s + 8, -8*s - 3];
    end function;
    all_in_H := function(H, s)
        return &and[IsSquare(H ! a) : a in squares_needed(s)];
    end function;
    assert exists(X){X : X in curves | X`D eq 26 and X`N eq 3 and X`W eq {1,3,26,78}};
    for row in table49 do
        d, s := Explode(row);
        H := ring_class_field(d);
        if d in bad_sign then
            assert not all_in_H(H, s);        // [GY]'s printed s is impossible ...
            assert all_in_H(H, -s);           // ... and the opposite sign is consistent.
            sc := Rationals() ! -s;
            K := IsSquare(sc) select QQ else NumberField(x^2 - sc);
            assert (d eq -267 and Degree(K) eq 1) or (d eq -708 and IsIsomorphic(K, QuadraticField(3)));
            assert DegreeOfFieldOfDefinitionOfCMPoint(X, d) eq Degree(K);
            assert same_fields(FieldsOfDefinitionOfCMPoint(X, d), [* K *]);
            assert same_fields(FieldsOfDefinitionOfCMPointFast(X, d), [* K *]);
            if Degree(K) eq 1 then
                assert d in Keys(RationalCMDiscs(X)) and d notin Keys(Degree2Points(X : compute_fields := false));
            else
                assert d in Keys(Degree2Points(X : compute_fields := false)) and d notin Keys(RationalCMDiscs(X));
            end if;
        else
            assert all_in_H(H, s);            // every other row of Table 49 passes as printed.
        end if;
    end for;
    // Uniqueness of the sign-corrected value (~1 s).  For d = -267 and -708, Pic(R) has exponent 2,
    // so H_R is the genus field, and a rational q is a square in H_R iff its squarefree part lies in
    // the group generated by the prime discriminants dividing d (Kummer theory; spot-checked against
    // IsSquare in H_R below).  Search all s = a/b, gcd(a,b) = 1, |a| <= 400, 1 <= b <= 400.
    sqf := func<n | Sign(n) * &*[Integers() | p[1] : p in Factorization(n) | IsOdd(p[2])]>;
    for d in bad_sign do
        R := QuadraticOrder(BinaryQuadraticForms(d));
        assert Exponent(PicardGroup(R)) le 2;
        pd := [(p mod 4 eq 1) select p else -p : p in PrimeDivisors(d) | p ne 2];
        if d div &*pd ne 1 then Append(~pd, d div &*pd); end if;     // the 2-part: -4, 8 or -8
        G := {sqf(&*[Integers() | pd[i] : i in S]) : S in Subsets({1..#pd})};
        H := ring_class_field(d);
        assert Degree(H) eq 2^#pd;
        assert &and[IsSquare(H ! q) eq (sqf(q) in G) : q in [-1, 2, -2, 3, -3, 5, 7, 59, -59, 89, -89, 177, -267]];
        is_sq := func<n | n eq 0 or sqf(n) in G>;
        // square classes of s, s^3-2s^2+9s+8, -8s-3 at s = a/b, cleared by even powers of b
        survivors := [a/b : a in [-400..400], b in [1..400] | GCD(a, b) eq 1 and is_sq(a*b)
                      and is_sq((-8*a - 3*b)*b) and is_sq((a^3 - 2*a^2*b + 9*a*b^2 + 8*b^3)*b)];
        s := [row[2] : row in table49 | row[1] eq d][1];
        assert survivors eq [-s];
    end for;
end procedure;

test_FieldOfDefinition();